#include <iostream>
#include <string>
using namespace std;

int main() {
    string x;
    getline(cin, x);
    for (size_t i = 1; i + 1 < x.length(); ++i) {
        if (x.substr(i, 2) == "at") {
            x.replace(i, 2, "@");
            break;
        }
    }
    size_t pos = 0;
    while ((pos = x.find("dot")) != string::npos) {
        x.replace(pos, 3, ".");
    }
    if (!x.empty() && x[0] == '.') {
        x.erase(0, 1);
        x = "dot" + x;
    }
    if (!x.empty() && x.back() == '.') {
        x.pop_back();
        x += "dot";
    }
    cout << x << endl;
    return 0;
}
